-- Reproducible seed for the 30-question physics section of every special-vehicle brevetto.
-- The original 8 questions per vehicle are retained; these 22 additions bring each
-- vehicle to 30 distinct physics questions. Technical and regulatory sections remain
-- gated until independently sourced banks are complete.
with land_questions as (
  select * from jsonb_to_recordset($land$[{"prompt":"A parità di raggio di curva, come varia l’accelerazione centripeta se la velocità aumenta del 50%?","options":["Diminuisce del 50%","Aumenta del 125%","Resta invariata","Aumenta del 50%"],"correct_index":1,"explanation":"Accelerazione centripeta proporzionale al quadrato della velocità. Il principio è valido in dinamica del veicolo; il comportamento effettivo dipende da massa, pneumatici, assetto e condizioni del fondo.","source_url":"https://www.physicsclassroom.com/class/circles/Lesson-1/Speed-and-the-Centripetal-Force","source_note":"Accelerazione centripeta proporzionale al quadrato della velocità"},{"prompt":"Che cosa accade alla componente del peso che agisce lungo una salita più ripida?","options":["Resta sempre identica","Aumenta","Dipende soltanto dal rapporto del cambio","Diminuisce fino ad annullarsi"],"correct_index":1,"explanation":"Scomposizione del peso sul piano inclinato. Il principio è valido in dinamica del veicolo; il comportamento effettivo dipende da massa, pneumatici, assetto e condizioni del fondo.","source_url":"https://www.physicsclassroom.com/class/vectors/Lesson-3/Inclined-Planes","source_note":"Scomposizione del peso sul piano inclinato"},{"prompt":"Che cosa descrive il sottosterzo in una curva?","options":["Il veicolo accelera senza comando","Il retrotreno perde aderenza prima dell’avantreno","Le ruote posteriori sterzano sempre in senso opposto","Il veicolo percorre una traiettoria più larga di quella richiesta dal volante"],"correct_index":3,"explanation":"Equilibrio delle forze laterali e comportamento in curva. Il principio è valido in dinamica del veicolo; il comportamento effettivo dipende da massa, pneumatici, assetto e condizioni del fondo.","source_url":"https://mechref.engr.illinois.edu/dyn/ava.html","source_note":"Equilibrio delle forze laterali e comportamento in curva"},{"prompt":"Che cosa indica il fenomeno del fading dei freni?","options":["Il blocco automatico del differenziale","L’aumento permanente dell’aderenza","La diminuzione della temperatura del liquido refrigerante","La riduzione dell’efficacia frenante dovuta al surriscaldamento"],"correct_index":3,"explanation":"Surriscaldamento e perdita di efficacia frenante. Il principio è valido in dinamica del veicolo; il comportamento effettivo dipende da massa, pneumatici, assetto e condizioni del fondo.","source_url":"https://www.nhtsa.gov/vehicle-safety/brakes","source_note":"Surriscaldamento e perdita di efficacia frenante"},{"prompt":"Che cosa può provocare una pressione di gonfiaggio insufficiente durante la marcia?","options":["La scomparsa della resistenza al rotolamento","La riduzione certa dello spazio di frenata","L’aumento automatico della pressione dell’olio","Maggiore flessione e riscaldamento dello pneumatico"],"correct_index":3,"explanation":"Sottogonfiaggio e accumulo di calore. Il principio è valido in dinamica del veicolo; il comportamento effettivo dipende da massa, pneumatici, assetto e condizioni del fondo.","source_url":"https://www.nhtsa.gov/vehicle-safety/tires","source_note":"Sottogonfiaggio e accumulo di calore"},{"prompt":"Che cosa rappresenta la quantità di moto di un veicolo?","options":["Il rapporto tra massa e accelerazione","Il prodotto tra potenza e pressione","La sola energia termica dei freni","Il prodotto tra massa e velocità"],"correct_index":3,"explanation":"Definizione di quantità di moto. Il principio è valido in dinamica del veicolo; il comportamento effettivo dipende da massa, pneumatici, assetto e condizioni del fondo.","source_url":"https://www.physicsclassroom.com/class/momentum/Lesson-1/Momentum","source_note":"Definizione di quantità di moto"},{"prompt":"Che cosa succede alla forza laterale necessaria in curva se il raggio si dimezza mantenendo la velocità?","options":["Raddoppia","Resta uguale","Diventa quattro volte maggiore","Si dimezza"],"correct_index":0,"explanation":"Relazione tra accelerazione centripeta e raggio. Il principio è valido in dinamica del veicolo; il comportamento effettivo dipende da massa, pneumatici, assetto e condizioni del fondo.","source_url":"https://www.physicsclassroom.com/class/circles/Lesson-1/Speed-and-the-Centripetal-Force","source_note":"Relazione tra accelerazione centripeta e raggio"},{"prompt":"In una frenata su fondo a bassa aderenza, perché è importante evitare manovre brusche?","options":["Perché la massa del veicolo diminuisce","Perché l’inerzia scompare","Perché il coefficiente d’attrito aumenta con la sterzata","Perché si può superare il margine di aderenza disponibile e perdere controllo"],"correct_index":3,"explanation":"Aderenza disponibile e controllo del veicolo. Il principio è valido in dinamica del veicolo; il comportamento effettivo dipende da massa, pneumatici, assetto e condizioni del fondo.","source_url":"https://www.nhtsa.gov/vehicle-safety/tires","source_note":"Aderenza disponibile e controllo del veicolo"},{"prompt":"Nel modello ideale, se la velocità raddoppia, come varia l’energia cinetica?","options":["Diventa quattro volte maggiore","Resta uguale","Si dimezza","Raddoppia"],"correct_index":0,"explanation":"Energia cinetica proporzionale al quadrato della velocità. Il principio è valido in dinamica del veicolo; il comportamento effettivo dipende da massa, pneumatici, assetto e condizioni del fondo.","source_url":"https://www.physicsclassroom.com/class/energy/Lesson-1/Kinetic-Energy","source_note":"Energia cinetica proporzionale al quadrato della velocità"},{"prompt":"Perché frenare e sterzare intensamente nello stesso istante può saturare l’aderenza?","options":["Perché la massa del veicolo diventa nulla","Perché il servosterzo spegne il motore","Perché l’ABS disattiva sempre lo sterzo","Perché le forze longitudinali e laterali condividono il margine di attrito dello pneumatico"],"correct_index":3,"explanation":"Interazione tra forze longitudinali e laterali dello pneumatico. Il principio è valido in dinamica del veicolo; il comportamento effettivo dipende da massa, pneumatici, assetto e condizioni del fondo.","source_url":"https://mechref.engr.illinois.edu/dyn/ava.html","source_note":"Interazione tra forze longitudinali e laterali dello pneumatico"},{"prompt":"Perché il carico sul tetto può peggiorare la stabilità in curva?","options":["Perché riduce la massa complessiva","Perché abbassa il baricentro","Perché aumenta il passo","Perché innalza il baricentro e aumenta il momento di rollio"],"correct_index":3,"explanation":"Baricentro e stabilità del veicolo. Il principio è valido in dinamica del veicolo; il comportamento effettivo dipende da massa, pneumatici, assetto e condizioni del fondo.","source_url":"https://www.nhtsa.gov/vehicle-safety/tires","source_note":"Baricentro e stabilità del veicolo"},{"prompt":"Perché il trasferimento di carico laterale aumenta durante una curva più intensa?","options":["Perché il motore sposta fisicamente il baricentro","Perché il veicolo perde massa","Perché la pressione atmosferica aumenta","Perché l’accelerazione laterale genera un momento rispetto al baricentro"],"correct_index":3,"explanation":"Trasferimento laterale di carico. Il principio è valido in dinamica del veicolo; il comportamento effettivo dipende da massa, pneumatici, assetto e condizioni del fondo.","source_url":"https://mechref.engr.illinois.edu/dyn/ava.html","source_note":"Trasferimento laterale di carico"},{"prompt":"Perché la forza massima trasmissibile da uno pneumatico dipende dall’aderenza disponibile?","options":["Perché aumenta sempre con la temperatura del motore","Perché dipende soltanto dalla cilindrata","Perché è indipendente dal fondo stradale","Perché il limite è legato al coefficiente d’attrito e al carico normale"],"correct_index":3,"explanation":"Aderenza pneumatico e forze longitudinali/laterali. Il principio è valido in dinamica del veicolo; il comportamento effettivo dipende da massa, pneumatici, assetto e condizioni del fondo.","source_url":"https://mechref.engr.illinois.edu/dyn/ava.html","source_note":"Aderenza pneumatico e forze longitudinali/laterali"},{"prompt":"Perché la potenza richiesta per vincere la resistenza aerodinamica cresce rapidamente con la velocità?","options":["Perché la potenza non dipende dalla velocità","Perché la forza resistente è inversamente proporzionale alla velocità","Perché la massa diminuisce in marcia","Perché la forza resistente cresce circa con v² e la potenza è forza per velocità"],"correct_index":3,"explanation":"Resistenza aerodinamica e potenza. Il principio è valido in dinamica del veicolo; il comportamento effettivo dipende da massa, pneumatici, assetto e condizioni del fondo.","source_url":"https://www.grc.nasa.gov/www/k-12/airplane/drageq.html","source_note":"Resistenza aerodinamica e potenza"},{"prompt":"Perché la resistenza aerodinamica diventa molto più rilevante alle alte velocità?","options":["Perché dipende solo dalla massa","Perché diminuisce con il quadrato della velocità","Perché è sempre costante","Perché cresce approssimativamente con il quadrato della velocità relativa dell’aria"],"correct_index":3,"explanation":"Equazione della resistenza aerodinamica. Il principio è valido in dinamica del veicolo; il comportamento effettivo dipende da massa, pneumatici, assetto e condizioni del fondo.","source_url":"https://www.grc.nasa.gov/www/k-12/airplane/drageq.html","source_note":"Equazione della resistenza aerodinamica"},{"prompt":"Perché la trazione integrale non garantisce una frenata più corta?","options":["Perché il sistema AWD disattiva i freni","Perché frena soltanto l’asse posteriore","Perché la massa del veicolo si annulla","Perché in frenata il limite principale dipende da pneumatici, aderenza e fondo"],"correct_index":3,"explanation":"Aderenza pneumatico e frenata. Il principio è valido in dinamica del veicolo; il comportamento effettivo dipende da massa, pneumatici, assetto e condizioni del fondo.","source_url":"https://www.nhtsa.gov/vehicle-safety/tires","source_note":"Aderenza pneumatico e frenata"},{"prompt":"Perché un veicolo più pesante richiede più energia per raggiungere la stessa velocità?","options":["Perché l’attrito scompare","Perché la velocità massima diventa sempre doppia","Perché il coefficiente d’aderenza aumenta automaticamente","Perché a parità di velocità possiede maggiore energia cinetica"],"correct_index":3,"explanation":"Energia cinetica e dipendenza dalla massa. Il principio è valido in dinamica del veicolo; il comportamento effettivo dipende da massa, pneumatici, assetto e condizioni del fondo.","source_url":"https://www.physicsclassroom.com/class/energy/Lesson-1/Kinetic-Energy","source_note":"Energia cinetica e dipendenza dalla massa"},{"prompt":"Qual è il ruolo principale degli ammortizzatori nella dinamica del veicolo?","options":["Sostituire il sistema frenante","Aumentare la cilindrata","Modificare la massa del veicolo","Dissipare energia delle oscillazioni della sospensione"],"correct_index":3,"explanation":"Smorzamento delle oscillazioni della sospensione. Il principio è valido in dinamica del veicolo; il comportamento effettivo dipende da massa, pneumatici, assetto e condizioni del fondo.","source_url":"https://www.monroe.com/technical-resources/ride-and-handling.html","source_note":"Smorzamento delle oscillazioni della sospensione"},{"prompt":"Qual è la funzione delle scanalature del battistrada sul fondo bagnato?","options":["Ridurre la massa non sospesa","Aumentare la cilindrata","Bloccare la rotazione della ruota","Favorire l’evacuazione dell’acqua dalla zona di contatto"],"correct_index":3,"explanation":"Battistrada, acqua e aderenza. Il principio è valido in dinamica del veicolo; il comportamento effettivo dipende da massa, pneumatici, assetto e condizioni del fondo.","source_url":"https://www.nhtsa.gov/vehicle-safety/tires","source_note":"Battistrada, acqua e aderenza"},{"prompt":"Qual è la funzione fondamentale dell’ABS durante una frenata intensa?","options":["Aumentare la potenza del motore","Garantire sempre lo spazio di arresto minimo","Sostituire gli pneumatici invernali","Ridurre il rischio di bloccaggio delle ruote e aiutare a mantenere la direzionalità"],"correct_index":3,"explanation":"Principio di funzionamento ABS. Il principio è valido in dinamica del veicolo; il comportamento effettivo dipende da massa, pneumatici, assetto e condizioni del fondo.","source_url":"https://www.nhtsa.gov/equipment/anti-lock-braking-systems-abs","source_note":"Principio di funzionamento ABS"},{"prompt":"Quale conseguenza ha una distribuzione asimmetrica del carico tra i lati del veicolo?","options":["Riduce automaticamente il baricentro","Aumenta sempre l’aderenza su entrambi i lati","Non produce alcun effetto dinamico","Può alterare il bilanciamento e il comportamento in curva"],"correct_index":3,"explanation":"Distribuzione dei carichi e stabilità. Il principio è valido in dinamica del veicolo; il comportamento effettivo dipende da massa, pneumatici, assetto e condizioni del fondo.","source_url":"https://mechref.engr.illinois.edu/dyn/ava.html","source_note":"Distribuzione dei carichi e stabilità"},{"prompt":"Quale effetto produce un aumento della resistenza al rotolamento?","options":["Annulla l’inerzia","Riduce sempre la temperatura degli pneumatici","Aumenta automaticamente la potenza disponibile","Richiede più forza propulsiva per mantenere la stessa velocità"],"correct_index":3,"explanation":"Resistenza al rotolamento e richiesta energetica. Il principio è valido in dinamica del veicolo; il comportamento effettivo dipende da massa, pneumatici, assetto e condizioni del fondo.","source_url":"https://www.energy.gov/eere/vehicles/fuel-economy-tips","source_note":"Resistenza al rotolamento e richiesta energetica"}]$land$::jsonb)
  as q(prompt text, options jsonb, correct_index smallint, explanation text, source_url text, source_note text)
),
sea_questions as (
  select * from jsonb_to_recordset($sea$[{"prompt":"Che cosa accade alla resistenza d’onda al crescere della velocità di un corpo dislocante?","options":["Può aumentare sensibilmente in funzione del regime di velocità e della formazione delle onde","Dipende esclusivamente dalla vernice","Resta sempre nulla","Diminuisce sempre in modo lineare"],"correct_index":0,"explanation":"Resistenza di formazione d’onda. Il comportamento effettivo dipende da geometria dello scafo, carico, condizioni meteomarine e configurazione dell’unità.","source_url":"https://ittc.info/media/10129/2021-ittc-dictionary.pdf","source_note":"Resistenza di formazione d’onda"},{"prompt":"Che cosa descrive il fenomeno del beccheggio?","options":["L’oscillazione angolare dell’unità attorno all’asse trasversale","Lo spostamento laterale senza rotazione","La rotazione attorno all’asse verticale","La variazione della salinità"],"correct_index":0,"explanation":"Moto oscillatorio longitudinale. Il comportamento effettivo dipende da geometria dello scafo, carico, condizioni meteomarine e configurazione dell’unità.","source_url":"https://dmna.ny.gov/forms/naval/NYNMINST_3120_2_MEBS_Seamanship_Manual.pdf","source_note":"Moto oscillatorio longitudinale"},{"prompt":"Che cosa descrive il rollio?","options":["L’oscillazione angolare dell’unità attorno all’asse longitudinale","L’avanzamento rettilineo","La rotazione dell’elica","La variazione di pescaggio a prua soltanto"],"correct_index":0,"explanation":"Moto oscillatorio trasversale. Il comportamento effettivo dipende da geometria dello scafo, carico, condizioni meteomarine e configurazione dell’unità.","source_url":"https://weh.maritime.edu/stcw/2001/MT-4241.html","source_note":"Moto oscillatorio trasversale"},{"prompt":"Che cosa descrive il termine assetto longitudinale (trim)?","options":["La differenza di immersione tra prua e poppa","La velocità angolare dell’elica","L’inclinazione trasversale verso dritta","La distanza tra due onde"],"correct_index":0,"explanation":"Assetto longitudinale dell’unità. Il comportamento effettivo dipende da geometria dello scafo, carico, condizioni meteomarine e configurazione dell’unità.","source_url":"https://weh.maritime.edu/stcw/2001/MT-4241.html","source_note":"Assetto longitudinale dell’unità"},{"prompt":"Che cosa indica un’altezza metacentrica positiva in condizioni iniziali?","options":["Una tendenza iniziale a raddrizzarsi dopo una piccola inclinazione","L’assenza di spinta idrostatica","Una condizione di capovolgimento inevitabile","La velocità massima raggiungibile"],"correct_index":0,"explanation":"Stabilità iniziale e altezza metacentrica. Il comportamento effettivo dipende da geometria dello scafo, carico, condizioni meteomarine e configurazione dell’unità.","source_url":"https://weh.maritime.edu/stcw/2001/MT-4241.html","source_note":"Stabilità iniziale e altezza metacentrica"},{"prompt":"Che cosa può accadere a un’unità che procede in acque poco profonde a velocità elevata?","options":["Può aumentare l’immersione dinamica e modificarsi l’assetto per effetto squat","La densità dell’acqua raddoppia","Il pescaggio diventa nullo","La resistenza idrodinamica scompare"],"correct_index":0,"explanation":"Effetto squat in acque ristrette. Il comportamento effettivo dipende da geometria dello scafo, carico, condizioni meteomarine e configurazione dell’unità.","source_url":"https://www.gov.uk/government/publications/port-marine-safety-code","source_note":"Effetto squat in acque ristrette"},{"prompt":"Che cosa può causare una ventilazione dell’elica vicino alla superficie?","options":["Aspirazione di aria e perdita di spinta","Aumento della densità dell’acqua","Aumento certo del rendimento","Blocco del timone"],"correct_index":0,"explanation":"Ventilazione dell’elica. Il comportamento effettivo dipende da geometria dello scafo, carico, condizioni meteomarine e configurazione dell’unità.","source_url":"https://ittc.info/media/10129/2021-ittc-dictionary.pdf","source_note":"Ventilazione dell’elica"},{"prompt":"Che cosa rappresenta il dislocamento di un’unità navale?","options":["La massa dell’acqua spostata, equivalente alla massa dell’unità in equilibrio","La lunghezza immersa dello scafo","La sola massa del carburante","La potenza installata dei motori"],"correct_index":0,"explanation":"Dislocamento e galleggiamento. Il comportamento effettivo dipende da geometria dello scafo, carico, condizioni meteomarine e configurazione dell’unità.","source_url":"https://www.nationalhistoricships.org.uk/sites/default/files/2025-02/stability_guidance_for_static_vessels_nhs-uk_30_jan_2025_version.pdf","source_note":"Dislocamento e galleggiamento"},{"prompt":"Che cosa si intende per cavitazione dell’elica?","options":["Formazione e collasso di cavità di vapore in zone di bassa pressione","Aumento della salinità","Formazione di ghiaccio sulla pala","Rotazione dell’elica senza acqua"],"correct_index":0,"explanation":"Cavitazione e fenomeni idrodinamici. Il comportamento effettivo dipende da geometria dello scafo, carico, condizioni meteomarine e configurazione dell’unità.","source_url":"https://ittc.info/media/10129/2021-ittc-dictionary.pdf","source_note":"Cavitazione e fenomeni idrodinamici"},{"prompt":"Come si definisce lo sbandamento trasversale permanente causato da carichi asimmetrici?","options":["List","Cavitazione","Trim","Deriva magnetica"],"correct_index":0,"explanation":"Distribuzione dei pesi e sbandamento. Il comportamento effettivo dipende da geometria dello scafo, carico, condizioni meteomarine e configurazione dell’unità.","source_url":"https://weh.maritime.edu/stcw/2001/MT-4241.html","source_note":"Distribuzione dei pesi e sbandamento"},{"prompt":"Da quali componenti dipende principalmente la resistenza idrodinamica di uno scafo in avanzamento?","options":["Dalla forma dello scafo, dalla superficie bagnata e dalle condizioni di moto","Soltanto dalla massa dell’equipaggio","Soltanto dal colore dello scafo","Dalla frequenza radio di bordo"],"correct_index":0,"explanation":"Componenti della resistenza idrodinamica. Il comportamento effettivo dipende da geometria dello scafo, carico, condizioni meteomarine e configurazione dell’unità.","source_url":"https://ittc.info/media/10129/2021-ittc-dictionary.pdf","source_note":"Componenti della resistenza idrodinamica"},{"prompt":"Perché il carico deve essere fissato prima della navigazione?","options":["Per impedire spostamenti che alterano assetto, sbandamento e stabilità","Per ridurre la densità dell’acqua","Per aumentare la velocità massima dichiarata","Per eliminare la resistenza dello scafo"],"correct_index":0,"explanation":"Stivaggio e stabilità. Il comportamento effettivo dipende da geometria dello scafo, carico, condizioni meteomarine e configurazione dell’unità.","source_url":"https://www.nationalhistoricships.org.uk/sites/default/files/2025-02/stability_guidance_for_static_vessels_nhs-uk_30_jan_2025_version.pdf","source_note":"Stivaggio e stabilità"},{"prompt":"Perché l’inerzia rende necessario pianificare con anticipo una manovra di arresto in mare?","options":["L’unità continua a possedere quantità di moto anche dopo la riduzione della potenza","La spinta di galleggiamento arresta l’unità","L’acqua annulla immediatamente il moto","Il timone blocca la propulsione automaticamente"],"correct_index":0,"explanation":"Inerzia e manovra navale. Il comportamento effettivo dipende da geometria dello scafo, carico, condizioni meteomarine e configurazione dell’unità.","source_url":"https://dmna.ny.gov/forms/naval/NYNMINST_3120_2_MEBS_Seamanship_Manual.pdf","source_note":"Inerzia e manovra navale"},{"prompt":"Perché la corrente può modificare la traiettoria rispetto al fondo anche se la prua è orientata correttamente?","options":["Perché la velocità rispetto all’acqua e quella rispetto al fondo sono vettori differenti","Perché il timone annulla ogni corrente","Perché la bussola misura la velocità","Perché la corrente modifica la massa dell’unità"],"correct_index":0,"explanation":"Composizione vettoriale della velocità e deriva. Il comportamento effettivo dipende da geometria dello scafo, carico, condizioni meteomarine e configurazione dell’unità.","source_url":"https://dmna.ny.gov/forms/naval/NYNMINST_3120_2_MEBS_Seamanship_Manual.pdf","source_note":"Composizione vettoriale della velocità e deriva"},{"prompt":"Perché spostare un peso verso l’alto può ridurre la stabilità trasversale?","options":["Aumenta l’altezza del baricentro e riduce il braccio raddrizzante disponibile","Abbassa il centro di gravità","Aumenta automaticamente il pescaggio a zero","Aumenta la densità dell’acqua"],"correct_index":0,"explanation":"Centro di gravità e stabilità. Il comportamento effettivo dipende da geometria dello scafo, carico, condizioni meteomarine e configurazione dell’unità.","source_url":"https://www.nationalhistoricships.org.uk/sites/default/files/2025-02/stability_guidance_for_static_vessels_nhs-uk_30_jan_2025_version.pdf","source_note":"Centro di gravità e stabilità"},{"prompt":"Perché un’unità può avere un dislocamento leggermente diverso in acqua dolce rispetto all’acqua marina?","options":["Perché cambia la densità del fluido e quindi il volume immerso necessario a equilibrare il peso","Perché la gravità scompare in acqua dolce","Perché cambia la massa dell’acciaio","Perché l’elica cambia diametro"],"correct_index":0,"explanation":"Densità del fluido e volume di carena immerso. Il comportamento effettivo dipende da geometria dello scafo, carico, condizioni meteomarine e configurazione dell’unità.","source_url":"https://opennaoe.org/books/hydrostatics-stability/ch01/","source_note":"Densità del fluido e volume di carena immerso"},{"prompt":"Perché una pala del timone genera una forza laterale quando investita da flusso d’acqua?","options":["Per la differenza di pressione prodotta dal suo angolo rispetto al flusso","Perché riduce la densità dell’acqua","Perché aumenta il peso dell’unità","Perché interrompe la spinta di galleggiamento"],"correct_index":0,"explanation":"Forze idrodinamiche sul timone. Il comportamento effettivo dipende da geometria dello scafo, carico, condizioni meteomarine e configurazione dell’unità.","source_url":"https://weh.maritime.edu/stcw/2001/MT-4241.html","source_note":"Forze idrodinamiche sul timone"},{"prompt":"Perché una superficie libera di liquido in un serbatoio parzialmente pieno può ridurre la stabilità?","options":["Il liquido si sposta e produce un effetto equivalente all’innalzamento del baricentro","Il serbatoio elimina la spinta di Archimede","Il liquido aumenta sempre il dislocamento senza spostarsi","La pressione atmosferica diventa nulla"],"correct_index":0,"explanation":"Effetto delle superfici libere sulla stabilità. Il comportamento effettivo dipende da geometria dello scafo, carico, condizioni meteomarine e configurazione dell’unità.","source_url":"https://www.nationalhistoricships.org.uk/sites/default/files/2025-02/stability_guidance_for_static_vessels_nhs-uk_30_jan_2025_version.pdf","source_note":"Effetto delle superfici libere sulla stabilità"},{"prompt":"Qual è l’effetto di una virata rapida su un’unità navale?","options":["Genera accelerazione laterale e può aumentare sbandamento e carichi dinamici","Riduce il dislocamento","Annulla la quantità di moto","Aumenta la profondità del fondale"],"correct_index":0,"explanation":"Accelerazione laterale e stabilità in virata. Il comportamento effettivo dipende da geometria dello scafo, carico, condizioni meteomarine e configurazione dell’unità.","source_url":"https://dmna.ny.gov/forms/naval/NYNMINST_3120_2_MEBS_Seamanship_Manual.pdf","source_note":"Accelerazione laterale e stabilità in virata"},{"prompt":"Quale effetto produce il vento laterale su un’unità con ampia opera morta?","options":["Può generare una forza di deriva e un momento d’imbardata","Aumenta la spinta dell’elica","Riduce sempre il dislocamento","Annulla la corrente"],"correct_index":0,"explanation":"Effetto del vento e superficie esposta. Il comportamento effettivo dipende da geometria dello scafo, carico, condizioni meteomarine e configurazione dell’unità.","source_url":"https://dmna.ny.gov/forms/naval/NYNMINST_3120_2_MEBS_Seamanship_Manual.pdf","source_note":"Effetto del vento e superficie esposta"},{"prompt":"Quale funzione svolge l’elica propulsiva?","options":["Trasferisce quantità di moto all’acqua generando una spinta sul mezzo","Riduce il dislocamento","Misura la profondità","Sostituisce il timone"],"correct_index":0,"explanation":"Propulsione a elica e generazione della spinta. Il comportamento effettivo dipende da geometria dello scafo, carico, condizioni meteomarine e configurazione dell’unità.","source_url":"https://ittc.info/media/10129/2021-ittc-dictionary.pdf","source_note":"Propulsione a elica e generazione della spinta"},{"prompt":"Secondo il principio di Archimede, la spinta idrostatica è pari a che cosa?","options":["Al peso del fluido spostato","Alla potenza dei motori","Al peso totale dell’imbarcazione a vuoto","Alla pressione atmosferica moltiplicata per la lunghezza"],"correct_index":0,"explanation":"Principio di Archimede e spinta di galleggiamento. Il comportamento effettivo dipende da geometria dello scafo, carico, condizioni meteomarine e configurazione dell’unità.","source_url":"https://opennaoe.org/books/hydrostatics-stability/ch01/","source_note":"Principio di Archimede e spinta di galleggiamento"}]$sea$::jsonb)
  as q(prompt text, options jsonb, correct_index smallint, explanation text, source_url text, source_note text)
),
targets(vehicle_id, domain) as (values
 ('cc-subaru-crosstrek','land'),('cc-iveco-50c17-op','land'),
 ('cc-defender-110','land'),('cc-jeep-wrangler','land'),
 ('gdf-classe-monti','sea'),('gdf-classe-di-bartolo','sea'),
 ('gdf-classe-bigliani-viii','sea'),('gdf-bso-139','sea')
)
insert into public.vehicle_brevetto_question_bank
(vehicle_id,prompt,options,correct_index,explanation,source_url,source_note,category,active)
select t.vehicle_id,q.prompt,q.options,q.correct_index,q.explanation,q.source_url,q.source_note,'physics',true
from targets t
cross join lateral (
  select * from land_questions where t.domain='land'
  union all
  select * from sea_questions where t.domain='sea'
) q
where not exists (
  select 1 from public.vehicle_brevetto_question_bank existing
  where existing.vehicle_id=t.vehicle_id
    and existing.category='physics'
    and lower(trim(existing.prompt))=lower(trim(q.prompt))
);
